// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Liveness and database check
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// Channels this device blocked, newest first
	// (GET /v1/channel-blocks)
	ListChannelBlocks(ctx context.Context, request ListChannelBlocksRequestObject) (ListChannelBlocksResponseObject, error)
	// Unblock a channel
	// (DELETE /v1/channel-blocks/{channel_id})
	UnblockChannel(ctx context.Context, request UnblockChannelRequestObject) (UnblockChannelResponseObject, error)
	// Not interested in this channel
	// (PUT /v1/channel-blocks/{channel_id})
	BlockChannel(ctx context.Context, request BlockChannelRequestObject) (BlockChannelResponseObject, error)
	// Runtime config the app needs
	// (GET /v1/config)
	GetConfig(ctx context.Context, request GetConfigRequestObject) (GetConfigResponseObject, error)
	// Batch of client events (max 200, deduplicated by id)
	// (POST /v1/events)
	PostEvents(ctx context.Context, request PostEventsRequestObject) (PostEventsResponseObject, error)
	// Next page of clips for this device in one language
	// (GET /v1/feed)
	GetFeed(ctx context.Context, request GetFeedRequestObject) (GetFeedResponseObject, error)
	// Learnable languages and native-language options
	// (GET /v1/languages)
	ListLanguages(ctx context.Context, request ListLanguagesRequestObject) (ListLanguagesResponseObject, error)
	// Erase this device's data
	// (DELETE /v1/me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// This device's user and preferences
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Change device preferences
	// (PATCH /v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// Remove a learning language (not the last one)
	// (DELETE /v1/me/languages/{code})
	DeleteMyLanguage(ctx context.Context, request DeleteMyLanguageRequestObject) (DeleteMyLanguageResponseObject, error)
	// Add a learning language or change its level or active flag
	// (PUT /v1/me/languages/{code})
	PutMyLanguage(ctx context.Context, request PutMyLanguageRequestObject) (PutMyLanguageResponseObject, error)
	// Liked clips, newest first
	// (GET /v1/me/likes)
	ListMyLikes(ctx context.Context, request ListMyLikesRequestObject) (ListMyLikesResponseObject, error)
	// Saved clips, newest first
	// (GET /v1/me/saves)
	ListMySaves(ctx context.Context, request ListMySavesRequestObject) (ListMySavesResponseObject, error)
	// Register an install (or re-register the same install)
	// (POST /v1/sessions/anonymous)
	CreateAnonymousSession(ctx context.Context, request CreateAnonymousSessionRequestObject) (CreateAnonymousSessionResponseObject, error)
	// Undo a hide (idempotent)
	// (DELETE /v1/videos/{id}/hide)
	UnhideVideo(ctx context.Context, request UnhideVideoRequestObject) (UnhideVideoResponseObject, error)
	// Hide a clip from this device forever
	// (PUT /v1/videos/{id}/hide)
	HideVideo(ctx context.Context, request HideVideoRequestObject) (HideVideoResponseObject, error)
	// Remove a like
	// (DELETE /v1/videos/{id}/like)
	UnlikeVideo(ctx context.Context, request UnlikeVideoRequestObject) (UnlikeVideoResponseObject, error)
	// Like a clip
	// (PUT /v1/videos/{id}/like)
	LikeVideo(ctx context.Context, request LikeVideoRequestObject) (LikeVideoResponseObject, error)
	// Report a clip
	// (POST /v1/videos/{id}/report)
	ReportVideo(ctx context.Context, request ReportVideoRequestObject) (ReportVideoResponseObject, error)
	// Remove a save
	// (DELETE /v1/videos/{id}/save)
	UnsaveVideo(ctx context.Context, request UnsaveVideoRequestObject) (UnsaveVideoResponseObject, error)
	// Save a clip
	// (PUT /v1/videos/{id}/save)
	SaveVideo(ctx context.Context, request SaveVideoRequestObject) (SaveVideoResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

